   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="（点头）也是在那个地方，我知道了莱斯坦斯，知道了链尉官你。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我曾幻想过，如果我能认识你，或许能为这件事带来一丝希望……但我只是一个游离边境的吟游诗人，而你是人类的英雄。", msg_color="", msg_size=0, talker="弦枝", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4529", 0, 0, -67, 207.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
