   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你静静听着弦枝的讲述，风带着雪花在你们的肩膀上堆积了起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你沉默着，吟游诗人也没有说话，只是轻轻地哼唱着那段你们初遇之时的旋律。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
