   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="玛格丽塔，我将这份传承交给你，但你若是想要放弃，我也毫无怨言。", msg_color="", msg_size=0, talker="已故的吟游诗人", audio="", img="arts/ui/bg/story/storybg_14_112.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="黄金时代已经结束了，有太多同胞为了它倒在了风雪中，我们耗尽一生奔走，终究也走到了尽头……", msg_color="", msg_size=0, talker="已故的吟游诗人", audio="", img="arts/ui/bg/story/storybg_14_112.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们热爱的文字，我们传颂的诗歌……所有的坚持都被这个国家和人民唾弃，即便是那座属于我们的源起之城，也早已和那个时代一同消失，留下来的只有灵魂被奴役后的钢筋铁骨……", msg_color="", msg_size=0, talker="已故的吟游诗人", audio="", img="arts/ui/bg/story/storybg_14_112.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
